import java.io.*; import java.util.*; import java.util.stream.*; class Result { public static long gridlandMetro(int n, int m, int k, List<List<Integer>> track) { Map<Integer, List<int[]>> rowMap = new HashMap<>(); for (List<Integer> t : track) { rowMap.computeIfAbsent(t.get(0), x -> new ArrayList<>()).add(new int[]{t.get(1), t.get(2)}); } long occupied = 0; for (List<int[]> intervals : rowMap.values()) { intervals.sort(Comparator.comparingInt(a -> a[0])); int start = intervals.get(0)[0]; int end = intervals.get(0)[1]; for (int i = 1; i < intervals.size(); i++) { int[] next = intervals.get(i); if (next[0] <= end + 1) { end = Math.max(end, next[1]); } else { occupied += (end - start + 1); start = next[0]; end = next[1]; } } occupied += (end - start + 1); } return (long) n * m - occupied; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" "); int n = Integer.parseInt(firstMultipleInput[0]); int m = Integer.parseInt(firstMultipleInput[1]); int k = Integer.parseInt(firstMultipleInput[2]); List<List<Integer>> track = new ArrayList<>(); IntStream.range(0, k).forEach(i -> { try { track.add(Stream.of(bufferedReader.readLine().replaceAll("\\s+$", "").split(" ")).map(Integer::parseInt).collect(Collectors.toList())); } catch (IOException ex) { throw new RuntimeException(ex); } }); long result = Result.gridlandMetro(n, m, k, track); System.out.println(result); bufferedReader.close(); } }